#include<bits/stdc++.h>

using namespace std;

#define mod 998244353
#define BD 500

int dp[200005]={0};
int dp2[505][505]={0};

int main(){
  int n;
  cin >> n;
  dp[0]=1;
  for(int i=0;i<n;i++){
    int a;
    cin >> a;
    for(int d=1;d<=BD;d++){
      dp[i]+=dp2[d][i%d];
      if(dp[i]>=mod){dp[i]-=mod;}
    }

    if(a<=BD){
      dp2[a][i%a]+=dp[i];
      if(dp2[a][i%a]>=mod){dp2[a][i%a]-=mod;}
    }
    else{
      for(int j=i+a;j<n;j+=a){
        dp[j]+=dp[i];
        if(dp[j]>=mod){dp[j]-=mod;}
      }
    }
  }

  int res=0;
  for(int i=0;i<n;i++){
    res+=dp[i];
    if(res>=mod){res-=mod;}
  }
  cout << res << "\n";
  return 0;
}
